def calculate_max_lantern_volume(a):
    s = a / 4
    # V(y) = s^2 * (a - 2y) + (2/3) * s^2 * sqrt(y^2 - s^2/4)
    # Optimal y occurs at 3*sqrt(y^2 - s^2/4) = y => 8y^2 = 9/4 * s^2
    y_opt = math.sqrt(2.25 * s**2 / 8)
    if y_opt < s/2: y_opt = s/2

    def get_v(y):
        if y < s/2: return 0
        return s**2 * (a - 2*y) + (2/3) * s**2 * math.sqrt(max(0, y**2 - s**2/4))

    return round(get_v(y_opt))

