def calculate_probability(type1_expired=5, type2_expired=3, total_cans=24, sample_size=10, expired_found=2, ratio_type1_to_type2=2):
    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return math.comb(n, r)

    # Prior probabilities
    p_type1 = ratio_type1_to_type2 / (ratio_type1_to_type2 + 1)
    p_type2 = 1 / (ratio_type1_to_type2 + 1)

    # Conditional probabilities P(2 expired | Type I) and P(2 expired | Type II)
    # Hypergeometric distribution: (kCr * (N-k)C(n-r)) / NCn
    prob_given_type1 = (nCr(type1_expired, expired_found) * nCr(total_cans - type1_expired, sample_size - expired_found)) / nCr(total_cans, sample_size)
    prob_given_type2 = (nCr(type2_expired, expired_found) * nCr(total_cans - type2_expired, sample_size - expired_found)) / nCr(total_cans, sample_size)

    # Bayes' Theorem: P(Type I | 2 expired) = [P(2|T1) * P(T1)] / [P(2|T1)*P(T1) + P(2|T2)*P(T2)]
    posterior_type1 = (prob_given_type1 * p_type1) / (prob_given_type1 * p_type1 + prob_given_type2 * p_type2)

    return round(posterior_type1, 2)

def count_circular_colorings(n, k):
    """
    Calculates the number of ways to color a cycle graph C_n with k colors
    such that no two adjacent vertices have the same color.
    The formula for the chromatic polynomial of a cycle graph C_n is P(C_n, k) = (k-1)^n + (-1)^n * (k-1).
    """
    if n == 0:
        return 0
    return (k - 1)**n + ((-1)**n) * (k - 1)

def find_max_speed(a, b, c, t_limit):
    # s(t) = a*t^3 + b*t^2 + c
    # v(t) = s'(t) = 3*a*t^2 + 2*b*t
    # To find max v(t), find v'(t) = 6*a*t + 2*b = 0
    # t_crit = -2*b / (6*a) = -b / (3*a)

    def v(t):
        return 3 * a * (t**2) + 2 * b * t

    t_crit = -b / (3 * a)

    candidates = [v(0), v(t_limit)]
    if 0 < t_crit < t_limit:
        candidates.append(v(t_crit))

    return max(candidates)

