def count_winning_sequences():
    # Board indices: 0 1 2 / 3 4 5 / 6 7 8
    winning_lines = [
        (0, 1, 2), (3, 4, 5), (6, 7, 8), # Rows
        (0, 3, 6), (1, 4, 7), (2, 5, 8), # Cols
        (0, 4, 8), (2, 4, 6)            # Diagonals
    ]

    def check_win(board, player):
        for line in winning_lines:
            if all(board[i] == player for i in line):
                return True
        return False

    count = 0
    # We need sequences of 5 moves. An moves at 1, 3, 5. Binh moves at 2, 4.
    # Total cells are 9. We pick 5 distinct cells in order.
    for p in permutations(range(9), 5):
        board = [None] * 9
        game_over = False
        for i in range(4):
            player = 'X' if i % 2 == 0 else 'O'
            board[p[i]] = player
            if check_win(board, player):
                game_over = True
                break

        if not game_over:
            board[p[4]] = 'X'
            if check_win(board, 'X'):
                count += 1
    return count

