def solve_min_cost(min_print, min_card, acac_print, acac_card, euc_print, euc_card, acac_cost, euc_cost, max_acac, max_euc):
    min_total_cost = float('inf')
    # We iterate through possible tonnages. Since the constraints are linear, 
    # the optimum is at the vertices of the feasible region.
    # To ensure precision and cover vertices, we check intersections of boundary lines.
    # Lines: x=0, x=max_acac, y=0, y=max_euc, 
    # 200x + 300y = 2800, 300x + 150y = 2400 (using problem values)
    # Generalizing: acac_print*x + euc_print*y = min_print, acac_card*x + euc_card*y = min_card

    # Boundary lines equations: a*x + b*y = c
    lines = [
        (1, 0, 0), (1, 0, max_acac), (0, 1, 0), (0, 1, max_euc),
        (acac_print, euc_print, min_print), (acac_card, euc_card, min_card)
    ]

    points = []
    for i in range(len(lines)):
        for j in range(i + 1, len(lines)):
            a1, b1, c1 = lines[i]
            a2, b2, c2 = lines[j]
            det = a1 * b2 - a2 * b1
            if det != 0:
                x = (c1 * b2 - c2 * b1) / det
                y = (a1 * c2 - a2 * c1) / det
                points.append((x, y))

    for x, y in points:
        if 0 <= x <= max_acac and 0 <= y <= max_euc:
            if acac_print * x + euc_print * y >= min_print - 1e-9 and acac_card * x + euc_card * y >= min_card - 1e-9:
                cost = x * acac_cost + y * euc_cost
                if cost < min_total_cost:
                    min_total_cost = cost

    return round(min_total_cost, 2)

