def solve_nozzle_probability(consumption_x, consumption_y, total_consumption, cluster_size):
    # Equation: x*consumption_x + y*consumption_y = total_consumption
    # x >= 1, y >= 1
    valid_configs = 0
    optimal_configs = 0

    # Iterate through possible values of y to find integer x
    # y must be at least 1. Max y is (total_consumption - consumption_x) // consumption_y
    for y in range(1, (total_consumption - consumption_x) // consumption_y + 1):
        remaining = total_consumption - (y * consumption_y)
        if remaining > 0 and remaining % consumption_x == 0:
            x = remaining // consumption_x
            valid_configs += 1
            if (x + y) % cluster_size == 0:
                optimal_configs += 1

    if valid_configs == 0:
        return 0.0

    return round(optimal_configs / valid_configs, 2)

