def calculate_right_triangle_probability():
    # Possible sums of two dice (2 to 12) and their frequencies
    sums_freq = {
        2: 1, 3: 2, 4: 3, 5: 4, 6: 5, 7: 6, 8: 5, 9: 4, 10: 3, 11: 2, 12: 1
    }
    total_outcomes_per_roll = 36
    total_combinations = (36**3)

    right_cases = 0
    # Iterate through all possible values of a, b, and t
    for a in range(2, 13):
        for b in range(2, 13):
            for t in range(2, 13):
                angle = (t - 1) * 15
                # A triangle with sides a, b and angle gamma is right-angled if:
                # 1. The angle gamma is 90 degrees
                # 2. The angle opposite to side a is 90 degrees (implies b^2 = a^2 + (side_c)^2, but we have angle gamma)
                # Actually, if angle gamma is 90, it's right. 
                # If angle gamma is not 90, it's right if a^2 = b^2 + c^2 or b^2 = a^2 + c^2.
                # Using Law of Cosines: c^2 = a^2 + b^2 - 2ab*cos(gamma)
                # Case 1: gamma = 90
                if angle == 90:
                    right_cases += sums_freq[a] * sums_freq[b] * sums_freq[t]
                else:
                    # Case 2: Angle opposite to a is 90 => a^2 = b^2 + c^2
                    # a^2 = b^2 + (a^2 + b^2 - 2ab*cos(gamma)) => 2b^2 = 2ab*cos(gamma) => cos(gamma) = b/a
                    # Case 3: Angle opposite to b is 90 => b^2 = a^2 + c^2
                    # b^2 = a^2 + (a^2 + b^2 - 2ab*cos(gamma)) => 2a^2 = 2ab*cos(gamma) => cos(gamma) = a/b
                    import math
                    cos_gamma = math.cos(math.radians(angle))
                    if math.isclose(cos_gamma, b/a) or math.isclose(cos_gamma, a/b):
                        right_cases += sums_freq[a] * sums_freq[b] * sums_freq[t]

    return round(right_cases / total_combinations, 2)

def solve_prob(dice_sides=6, angle_multiplier=15, angle_offset=1):
    # Generalizing the logic for the function to accept parameters
    sums_freq = {}
    for i in range(1, dice_sides + 1):
        for j in range(1, dice_sides + 1):
            s = i + j
            sums_freq[s] = sums_freq.get(s, 0) + 1

    total_outcomes_per_roll = dice_sides**2
    total_combinations = (total_outcomes_per_roll**3)
    right_cases = 0

    import math
    possible_sums = list(sums_freq.keys())
    for a in possible_sums:
        for b in possible_sums:
            for t in possible_sums:
                angle = (t - angle_offset) * angle_multiplier
                if angle == 90:
                    right_cases += sums_freq[a] * sums_freq[b] * sums_freq[t]
                else:
                    cos_gamma = math.cos(math.radians(angle))
                    if math.isclose(cos_gamma, b/a) or math.isclose(cos_gamma, a/b):
                        right_cases += sums_freq[a] * sums_freq[b] * sums_freq[t]

    return round(right_cases / total_combinations, 2)

def maximize_profit(c_const, c_lin, c_quad, c_cub, p_const, p_lin):
    # Profit P(x) = Revenue R(x) - Cost C(x)
    # R(x) = x * p(x) = x * (p_const + p_lin * x) = p_const*x + p_lin*x^2
    # P(x) = (p_const*x + p_lin*x^2) - (c_const + c_lin*x + c_quad*x^2 + c_cub*x^3)
    # P(x) = -c_cub*x^3 + (p_lin - c_quad)*x^2 + (p_const - c_lin)*x - c_const
    # P'(x) = -3*c_cub*x^2 + 2*(p_lin - c_quad)*x + (p_const - c_lin)
    # Solve P'(x) = 0 using quadratic formula: ax^2 + bx + c = 0
    a = -3 * c_cub
    b = 2 * (p_lin - c_quad)
    c = p_const - c_lin

    discriminant = b**2 - 4*a*c
    if discriminant < 0:
        return None

    x1 = (-b + discriminant**0.5) / (2 * a)
    x2 = (-b - discriminant**0.5) / (2 * a)

    # P''(x) = -6*c_cub*x + 2*(p_lin - c_quad)
    # For maximum, P''(x) < 0
    def p_double_prime(x):
        return -6 * c_cub * x + 2 * (p_lin - c_quad)

    if p_double_prime(x1) < 0:
        return round(x1)
    elif p_double_prime(x2) < 0:
        return round(x2)
    return None

