def calculate_initial_deposit(interest_rate, years, target_amount):
    # Formula for compound interest: A = P(1 + r)^n
    # P = A / (1 + r)^n
    initial_deposit = target_amount / ((1 + interest_rate / 100) ** years)
    return math.ceil(initial_deposit)

