def calculate_salary_diff(start_salary, inc_fixed, inc_percent, duration_years):
    # Option 1: Fixed increase every 3 years
    total1 = 0
    current_salary1 = start_salary
    for year in range(1, duration_years + 1):
        if year > 1 and (year - 1) % 3 == 0:
            current_salary1 += inc_fixed
        total1 += current_salary1 * 12

    # Option 2: Percentage increase every 3 years
    total2 = 0
    current_salary2 = start_salary
    for year in range(1, duration_years + 1):
        if year > 1 and (year - 1) % 3 == 0:
            current_salary2 *= (1 + inc_percent)
        total2 += current_salary2 * 12

    return round(total2 - total1)

