def calculate_savings(initial_salary, growth_rate, months):
    total_savings = 0
    current_salary = initial_salary
    for month in range(2, months + 1):
        previous_salary = current_salary
        current_salary = previous_salary * (1 + growth_rate)
        savings_this_month = current_salary - previous_salary
        total_savings += savings_this_month
    return round(total_savings)

from math import comb

def calculate_probability_score(num_questions, num_options, correct_pts, wrong_pts, target_score):
    # Let x be the number of correct answers, (num_questions - x) be the number of wrong answers
    # Score = x * correct_pts + (num_questions - x) * wrong_pts
    # target_score = x * (correct_pts - wrong_pts) + num_questions * wrong_pts

    # Solving for x:
    # x = (target_score - num_questions * wrong_pts) / (correct_pts - wrong_pts)

    numerator = target_score - (num_questions * wrong_pts)
    denominator = correct_pts - wrong_pts

    if numerator % denominator != 0:
        return round(0.0, 2)

    x = numerator // denominator

    if x < 0 or x > num_questions:
        return round(0.0, 2)

    prob_correct = 1 / num_options
    prob_wrong = (num_options - 1) / num_options

    # Binomial probability: P(X=x) = comb(n, x) * p^x * (1-p)^(n-x)
    p = comb(num_questions, x) * (prob_correct**x) * (prob_wrong**(num_questions - x))
    return round(100 * p, 2)

