def calculate_loss_probability(hai_n, son_n, pick_k):
    hai_combos = list(combinations(range(1, hai_n + 1), pick_k))
    son_combos = list(combinations(range(1, son_n + 1), pick_k))

    def get_number(combo):
        sorted_combo = sorted(combo, reverse=True)
        return int(''.join(map(str, sorted_combo)))

    hai_nums = [get_number(c) for c in hai_combos]
    son_nums = [get_number(c) for c in son_combos]

    son_losses = 0
    for h in hai_nums:
        for s in son_nums:
            if h > s:
                son_losses += 1

    prob = son_losses / (len(hai_nums) * len(son_nums))
    return round(prob, 2)
